import { readFile, writeFile, mkdir, rename, unlink } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { randomUUID } from 'node:crypto';

function migrate(config, options) {
  if (!config || typeof config !== 'object' || Array.isArray(config)) {
    throw new TypeError('Config must be a JSON object');
  }
  if (config.version === 3) {
    return options.region === undefined ? config : { ...config, region: options.region };
  }
  if (config.version !== 1) throw new Error(`Unsupported config version: ${config.version}`);

  const known = new Set(['version', 'name', 'timeoutSeconds', 'flags', 'region', 'retry', 'legacy', 'timeoutMs', 'features']);
  const legacy = { ...config.legacy };
  for (const [key, value] of Object.entries(config)) {
    if (!known.has(key)) {
      Object.defineProperty(legacy, key, { value, enumerable: true, writable: true, configurable: true });
    }
  }
  const result = {
    version: 3,
    ...(Object.hasOwn(config, 'name') ? { name: config.name } : {}),
    region: options.region ?? config.region ?? 'eu-north-7',
    retry: { maxAttempts: 5, backoffMs: 125, ...config.retry },
    features: Object.entries(config.flags ?? {}).filter(([, enabled]) => enabled === true).map(([name]) => name).sort(),
  };
  if (Object.hasOwn(config, 'timeoutSeconds')) result.timeoutMs = config.timeoutSeconds * 1000;
  else if (Object.hasOwn(config, 'timeoutMs')) result.timeoutMs = config.timeoutMs;
  if (Object.keys(legacy).length) result.legacy = legacy;
  return result;
}

export async function migrateFile(inputPath, outputPath, options = {}) {
  const directory = dirname(resolve(outputPath));
  const backupPath = join(directory, 'backups', 'source.json');
  const source = await readFile(inputPath);
  let config;
  try {
    config = JSON.parse(source.toString('utf8'));
  } catch (error) {
    if (!(error instanceof SyntaxError)) throw error;
    // Verify the recovery copy before moving any customer data.
    config = JSON.parse(await readFile(backupPath, 'utf8'));
    const recoveryDirectory = join(directory, 'recovery');
    await mkdir(recoveryDirectory, { recursive: true });
    const recoveryPath = join(recoveryDirectory, 'source.bad.json');
    // Exclusive creation ensures a previous recovery is never overwritten.
    await writeFile(recoveryPath, source, { flag: 'wx' });
    await unlink(inputPath);
  }
  const result = migrate(config, options);
  await mkdir(dirname(backupPath), { recursive: true });
  try {
    await writeFile(backupPath, source, { flag: 'wx' });
  } catch (error) {
    if (error.code !== 'EEXIST') throw error;
  }
  const temporaryPath = join(directory, `.migration-${randomUUID()}.tmp`);
  try {
    await writeFile(temporaryPath, `${JSON.stringify(result, null, 2)}\n`, { flag: 'wx' });
    await rename(temporaryPath, outputPath);
  } finally {
    await unlink(temporaryPath).catch(error => {
      if (error.code !== 'ENOENT') throw error;
    });
  }
  return result;
}

#!/usr/bin/env node
// Usage: node bin/migrate.mjs INPUT OUTPUT [REGION_OVERRIDE]
import { migrateFile } from '../src/migrate.mjs';

const args = process.argv.slice(2);
if (args.length < 2 || args.length > 3) {
  console.error('Usage: node bin/migrate.mjs INPUT OUTPUT [REGION_OVERRIDE]');
  process.exitCode = 1;
} else {
  try {
    const result = await migrateFile(args[0], args[1], args.length === 3 ? { region: args[2] } : {});
    console.log(JSON.stringify(result, null, 2));
  } catch (error) {
    console.error(`Migration failed: ${error.message}`);
    process.exitCode = 1;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, mkdir, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { migrateFile } from '../src/migrate.mjs';

test('defaults, exact backup, invocation override and v3 preservation', async () => {
  const d = await mkdtemp(join(process.cwd(), '.policies-'));
  try {
    const input = join(d, 'input.json'), output = join(d, 'output.json');
    const source = '{ "version":1,"name":"customer","custom":{"keep":true} }\n';
    await writeFile(input, source);
    const result = await migrateFile(input, output);
    assert.equal(result.region, 'eu-north-7');
    assert.deepEqual(result.retry, { maxAttempts: 5, backoffMs: 125 });
    assert.deepEqual(result.legacy, { custom: { keep: true } });
    assert.equal(await readFile(join(d, 'backups/source.json'), 'utf8'), source);
    assert.equal((await migrateFile(input, output, { region: 'temporary' })).region, 'temporary');
    assert.equal((await migrateFile(input, output)).region, 'eu-north-7');
    const v3 = { version: 3, custom: true, features: ['z', 'a'] };
    await writeFile(input, JSON.stringify(v3));
    assert.deepEqual(await migrateFile(input, output), v3);
    assert.deepEqual(await migrateFile(input, output, { region: 'explicit' }), { ...v3, region: 'explicit' });
    assert.equal(await readFile(join(d, 'backups/source.json'), 'utf8'), source);
  } finally { await rm(d, { recursive: true, force: true }); }
});

test('truncated input recovers without altering backup', async () => {
  const d = await mkdtemp(join(process.cwd(), '.recovery-'));
  try {
    const input = join(d, 'input.json');
    await mkdir(join(d, 'backups'));
    const backup = '{"version":1,"custom":{"original":true}}\n';
    await writeFile(join(d, 'backups/source.json'), backup);
    await writeFile(input, '{"version":');
    const result = await migrateFile(input, join(d, 'output.json'));
    assert.deepEqual(result.legacy, { custom: { original: true } });
    assert.equal(await readFile(join(d, 'backups/source.json'), 'utf8'), backup);
    assert.equal(await readFile(join(d, 'recovery/source.bad.json'), 'utf8'), '{"version":');
    await assert.rejects(readFile(input), { code: 'ENOENT' });
  } finally { await rm(d, { recursive: true, force: true }); }
});

